SELECT * FROM (SELECT CASE WHEN shipping_fee >= 35 THEN 'high' WHEN shipping_fee >= 6 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, MIN(order_date) AS first_order_date, COUNT(CASE WHEN status = 'COMPLETED' THEN 1 END) AS completed_count FROM orders GROUP BY CASE WHEN shipping_fee >= 35 THEN 'high' WHEN shipping_fee >= 6 THEN 'mid' ELSE 'low' END) AS sub WHERE completed_count >= 9 ORDER BY first_order_date, shipping_fee_bucket DESC
